import type { Question, StudyModule } from "../module-types";

// ---------- MAT-01: Material Properties ----------

const lessonsProperties=[
{title:"Stress-strain diagram fundamentals",body:"On an engineering stress-strain curve, the initial straight-line portion has a slope equal to the modulus of elasticity, E=σ/ε (Hooke's law). The yield strength marks the onset of significant plastic deformation — for metals without a sharp yield point, it is found by the 0.2% offset method. The ultimate tensile strength (UTS) is the maximum stress reached on the ENGINEERING curve, not the stress at fracture; for ductile metals, necking causes the engineering stress to drop after UTS is reached, so fracture occurs at a lower stress than UTS."},
{title:"Ductility, hardness, and brittleness",body:"Ductility is commonly quantified by percent elongation, %EL=(Lf−L0)/L0×100, always using the ORIGINAL gauge length L0 in the denominator. Brittle materials fracture with little or no plastic deformation and a nearly linear stress-strain curve up to a sudden failure, while ductile materials show extended yielding and necking. Hardness (e.g., Brinell BHN) measures resistance to permanent indentation and correlates roughly with strength — for steels, UTS(MPa)≈3.45×BHN — but hardness is a separate property from elastic modulus, which stays essentially constant regardless of heat treatment."},
{title:"Density and specific weight",body:"Density is mass per unit volume, ρ=m/V, typically in kg/m³ or g/cm³. Common structural metals have distinct densities — aluminum≈2.70 g/cm³, titanium≈4.51 g/cm³, steel≈7.87 g/cm³, copper≈8.96 g/cm³ — useful both for identifying an unknown material and for weight-sensitive design calculations."},
{title:"Thermal expansion",body:"When a material's temperature changes, its length changes by δ=αLΔT, where α is the coefficient of linear thermal expansion (units of 1/°C or 1/°F), L is the original length, and ΔT is the CHANGE in temperature (final minus initial) — never the final temperature alone. Constrained members that are prevented from expanding or contracting freely develop thermal stress instead of thermal strain."}
];

const flashcardsProperties=[
{front:"Modulus of elasticity",back:"E=σ/ε",note:"Slope of the initial straight-line (elastic) portion of the stress-strain curve."},
{front:"Percent elongation",back:"%EL=(Lf−L0)/L0×100",note:"Always divide by the ORIGINAL gauge length L0, not the final length."},
{front:"Ultimate tensile strength",back:"The maximum stress on the engineering stress-strain curve",note:"Not the same as the fracture stress — necking drops the stress before fracture in ductile metals."},
{front:"Yield strength (0.2% offset)",back:"Stress where a line parallel to the elastic slope, offset 0.002 strain, intersects the curve",note:"Used when there's no sharp yield point."},
{front:"Density",back:"ρ=m/V",note:"Steel≈7.87 g/cm³, aluminum≈2.70 g/cm³, titanium≈4.51 g/cm³, copper≈8.96 g/cm³."},
{front:"Thermal expansion",back:"δ=αLΔT",note:"ΔT is final minus initial temperature — never the final temperature alone."},
{front:"Hardness-strength correlation (steel)",back:"UTS(MPa)≈3.45×BHN",note:"Hardness tracks strength, not elastic modulus, which is essentially unaffected by heat treatment."}
];

const questionsProperties:Question[]=[
{id:"MAT01-Q01",skill:"Modulus of elasticity",difficulty:"Easy",prompt:"A tension test shows that a stress of 210 MPa produces a strain of 0.0015 within the linear-elastic region. Find the modulus of elasticity E.",choices:["70 GPa","140 GPa","210 GPa","280 GPa"],answer:1,explanation:"E is about 140 GPa.",solution:"Step 1 — Hooke's law: E=σ/ε.\nStep 2 — Substitute: E=210 MPa/0.0015.\nStep 3 — E=140,000 MPa.\nFinal answer: 140 GPa.",trap:"70 GPa results from mistakenly doubling the strain value (using ε=0.003 instead of the given 0.0015) before dividing, which halves the computed modulus.",repair:"Substitute the exact strain value given in the problem — don't round or adjust it before dividing."},
{id:"MAT01-Q02",skill:"Ductility (percent elongation)",difficulty:"Easy",prompt:"A tensile specimen has an original gauge length of 50 mm. After fracture, the gauge length measures 61.5 mm. Find the percent elongation.",choices:["11.5%","18.7%","23.0%","30.7%"],answer:2,explanation:"The percent elongation is 23.0%.",solution:"Step 1 — %EL=(Lf−L0)/L0×100.\nStep 2 — Substitute: (61.5−50)/50×100=11.5/50×100.\nFinal answer: 23.0%.",trap:"18.7% comes from dividing the elongation by the FINAL gauge length (11.5/61.5×100) instead of the original gauge length.",repair:"Percent elongation always uses the ORIGINAL gauge length L0 in the denominator, never the final length."},
{id:"MAT01-Q03",skill:"Stress-strain diagram concepts",difficulty:"Medium",prompt:"On an engineering stress-strain curve for a ductile metal, the ultimate tensile strength corresponds to:",choices:["The stress at first yielding","The maximum stress reached on the curve","The stress at the moment of fracture","The slope of the initial linear region"],answer:1,explanation:"UTS is the peak (maximum) engineering stress on the curve.",solution:"Step 1 — After yielding, a ductile metal continues to strain-harden, so stress keeps rising with strain for a while.\nStep 2 — The stress reaches a peak value — this peak is defined as the ultimate tensile strength.\nStep 3 — Beyond this peak, necking begins and the engineering stress DECREASES even though true stress keeps rising, until fracture occurs at a lower engineering stress than the peak.\nFinal answer: The maximum stress reached on the curve.",trap:"Choosing 'the stress at the moment of fracture' confuses UTS with the fracture stress — for a ductile metal, necking causes the engineering stress to drop after UTS, so the fracture point sits below (not at) the peak.",repair:"UTS is the CURVE'S PEAK stress; fracture stress is a separate, lower point that occurs after necking begins."},
{id:"MAT01-Q04",skill:"Density",difficulty:"Medium",prompt:"A metal sample has a mass of 356 g and a volume of 45.3 cm³. Given common densities — aluminum≈2.70, titanium≈4.51, steel≈7.87, copper≈8.96 g/cm³ — which material does this sample most closely match?",choices:["Aluminum (≈2.70 g/cm³)","Titanium (≈4.51 g/cm³)","Steel (≈7.87 g/cm³)","Copper (≈8.96 g/cm³)"],answer:2,explanation:"The computed density (≈7.86 g/cm³) matches steel most closely.",solution:"Step 1 — ρ=m/V=356 g/45.3 cm³.\nStep 2 — ρ≈7.86 g/cm³.\nStep 3 — Compare to the reference list: 7.86 g/cm³ is closest to steel's 7.87 g/cm³, not aluminum, titanium, or copper.\nFinal answer: Steel (≈7.87 g/cm³).",trap:"Copper (≈8.96 g/cm³) is a tempting error if the volume is carelessly rounded down (e.g., to about 40 cm³) before dividing — 356/40≈8.9, which lands close to copper's density instead of the correctly computed 7.86 g/cm³.",repair:"Carry the given volume through the division at full precision (45.3 cm³, not a rounded estimate) before comparing to reference densities."},
{id:"MAT01-Q05",skill:"Thermal expansion",difficulty:"Medium",prompt:"A steel beam (α=11.7×10⁻⁶ /°C) is 12 m long and installed at 10°C. Find its change in length when the temperature rises to 45°C.",choices:["3.51 mm","4.91 mm","6.32 mm","9.83 mm"],answer:1,explanation:"The beam elongates by about 4.91 mm.",solution:"Step 1 — ΔT is the temperature CHANGE: ΔT=45−10=35°C.\nStep 2 — δ=αLΔT=(11.7×10⁻⁶)(12 m)(35°C).\nStep 3 — δ=11.7×10⁻⁶×420=4914×10⁻⁶ m.\nFinal answer: 4.91 mm.",trap:"6.32 mm results from using the final temperature (45°C) directly as ΔT instead of the actual 35°C change (45−10), overstating the elongation.",repair:"ΔT is always (final temperature − initial temperature) — never the final temperature used alone."},
{id:"MAT01-Q06",skill:"Hardness and strength",difficulty:"Medium",prompt:"Two steel samples are tested: Sample A has a higher Brinell hardness number (BHN) than Sample B, and both are otherwise the same alloy. What does this most directly indicate about Sample A relative to Sample B?",choices:["Sample A has lower tensile strength and higher ductility","Sample A has higher tensile strength and typically lower ductility","Sample A has a larger elastic modulus","Sample A has a lower melting point"],answer:1,explanation:"Higher hardness in the same alloy correlates with higher strength and typically reduced ductility.",solution:"Step 1 — For steels, hardness correlates roughly linearly with tensile strength (UTS(MPa)≈3.45×BHN).\nStep 2 — A higher BHN in the same alloy therefore indicates higher tensile strength.\nStep 3 — Higher hardness/strength (often from heat treatment such as quenching) typically comes at the cost of reduced ductility.\nFinal answer: Sample A has higher tensile strength and typically lower ductility.",trap:"Choosing 'a larger elastic modulus' incorrectly extends the hardness-strength correlation to stiffness — E is governed by atomic bonding and stays essentially constant for a given base metal regardless of hardness or heat treatment.",repair:"Hardness tracks strength (resistance to plastic deformation), not the elastic modulus, which does not change meaningfully with heat treatment."},
{id:"MAT01-Q07",skill:"Thermal expansion (design application)",difficulty:"Hard",prompt:"A steel pipe segment is 25 m long at its installation temperature of 15°C. An expansion joint must be sized for a maximum service temperature of 95°C, using α=12×10⁻⁶ /°C. What minimum gap must the expansion joint accommodate?",choices:["9.0 mm","19.2 mm","24.0 mm","28.8 mm"],answer:2,explanation:"The joint must accommodate about 24.0 mm of expansion.",solution:"Step 1 — ΔT=95−15=80°C.\nStep 2 — δ=αLΔT=(12×10⁻⁶)(25 m)(80°C).\nStep 3 — δ=12×10⁻⁶×2000=24,000×10⁻⁶ m.\nFinal answer: 24.0 mm.",trap:"19.2 mm results from mistakenly using a pipe length of 20 m instead of the stated 25 m.",repair:"Substitute the exact given length into δ=αLΔT — double-check every value against the problem statement before calculating."},
{id:"MAT01-Q08",skill:"Fracture appearance",difficulty:"Hard",prompt:"A fractured sample shows almost no visible necking and no yielding region on its stress-strain curve — the curve is nearly linear right up to a sudden fracture. This behavior is most characteristic of:",choices:["A ductile metal such as annealed copper","A brittle material such as gray cast iron or a ceramic","A metal tested well above its yield strength","A polymer well above its glass transition temperature"],answer:1,explanation:"Near-linear response with sudden fracture and no necking is classic brittle behavior.",solution:"Step 1 — Ductile behavior is defined by extended plastic deformation (yielding) and visible necking before fracture.\nStep 2 — The described sample shows neither — a linear response followed by sudden failure.\nStep 3 — This is the defining signature of brittle fracture, seen in materials like gray cast iron (graphite flakes act as internal stress risers) or ceramics.\nFinal answer: A brittle material such as gray cast iron or a ceramic.",trap:"Choosing 'a ductile metal such as annealed copper' assumes all metals behave ductilely, but a brittle metal such as cast iron produces exactly this near-linear, no-necking fracture curve.",repair:"Judge ductility from the stress-strain curve's actual SHAPE (yielding and necking present or absent) — not from the general category of 'metal vs. nonmetal.'"},
{id:"MAT01-Q09",skill:"Modulus of elasticity from test data",difficulty:"Medium",prompt:"A bar with a cross-sectional area of 200 mm² and a length of 1.5 m is loaded axially with 40 kN, producing an elastic elongation of 1.2 mm. Determine the modulus of elasticity.",choices:["83.3 GPa","125.0 GPa","200.0 GPa","250.0 GPa"],answer:3,explanation:"The modulus of elasticity is about 250 GPa.",solution:"Step 1 — σ=P/A=40,000 N/200 mm²=200 MPa.\nStep 2 — ε=δ/L=1.2 mm/1500 mm=0.0008.\nStep 3 — E=σ/ε=200 MPa/0.0008.\nFinal answer: 250 GPa.",trap:"200.0 GPa mistakes the computed stress value (200 MPa) for the modulus itself, skipping the final division by strain entirely.",repair:"E is stress DIVIDED by strain — always complete both steps, ε=δ/L and then E=σ/ε, rather than stopping after computing stress."},
{id:"MAT01-Q10",skill:"Hardness-strength conversion",difficulty:"Hard",prompt:"Using the approximate empirical relationship for steel, UTS(MPa)≈3.45×BHN, estimate the ultimate tensile strength of a steel sample with a Brinell hardness of 250 BHN.",choices:["725 MPa","862.5 MPa","900 MPa","1035 MPa"],answer:1,explanation:"The estimated UTS is about 862.5 MPa.",solution:"Step 1 — UTS≈3.45×BHN.\nStep 2 — Substitute the given hardness: UTS≈3.45×250.\nFinal answer: 862.5 MPa.",trap:"1035 MPa results from mistakenly substituting BHN=300 (an easy misread of the given 250) into the formula: 3.45×300=1035.",repair:"Double-check the given numeric value before substituting into an empirical formula — use the stated 250, not a misread 300."}
];

export const materialsPropertiesModule:StudyModule={id:"MAT-01",subjectId:"materials",sectionId:"properties",title:"Material Properties",lessons:lessonsProperties,flashcards:flashcardsProperties,questions:questionsProperties};

// ---------- MAT-02: Phase Diagrams and Heat Treatment ----------

const lessonsPhaseDiagrams=[
{title:"Reading a binary phase diagram",body:"A binary phase diagram plots temperature versus composition (weight or atomic percent of the second component). The liquidus line separates all-liquid from partially solidified regions; the solidus line separates fully solid from partially melted regions. At a given temperature inside a two-phase region, a horizontal tie line connects the compositions of the two coexisting phases — always read those two endpoint compositions off the diagram before applying the lever rule."},
{title:"The lever rule",body:"Within a two-phase region, the weight fraction of a given phase equals the length of the tie-line arm on the OPPOSITE side of that phase, divided by the total tie-line length: fraction of a phase=(C0−C_near)/(C_far−C_near), where C0 is the overall alloy composition and the near/far compositions are the two phase-boundary values labeled consistently. The lever rule only applies inside two-phase regions — inside a single-phase field, that phase's fraction is trivially 1.0."},
{title:"Eutectic reactions",body:"The eutectic point is a specific (composition, temperature) pair — typically the lowest-melting composition in the system — where liquid transforms directly and isothermally into two solid phases: L→α+β. Only the exact eutectic composition solidifies at one constant temperature; every other composition solidifies over a range between its liquidus and solidus."},
{title:"Common heat treatments",body:"Annealing (slow furnace cooling from an elevated temperature) softens a metal, increases ductility, and relieves internal stresses. Normalizing (air cooling from the austenitizing temperature) cools faster than annealing, producing finer grains and higher strength/hardness than a fully annealed part. Quenching (rapid cooling, e.g., in water or oil) produces the highest hardness — in steel, by trapping carbon in the martensite structure — but leaves the part brittle. Tempering (reheating a quenched part to a moderate temperature, then cooling) reduces that brittleness and relieves internal stresses while retaining most of the strength gained by quenching."}
];

const flashcardsPhaseDiagrams=[
{front:"Tie line",back:"Horizontal line connecting the compositions of two coexisting phases at a given temperature",note:"Only exists inside a two-phase region of the diagram."},
{front:"Lever rule",back:"Fraction of a phase = (opposite arm of the tie line) ÷ (total tie-line length)",note:"Always confirm which phase's fraction is being asked for before dividing."},
{front:"Eutectic point",back:"The single composition/temperature where L→α+β isothermally",note:"Usually the lowest-melting composition in the system."},
{front:"Annealing",back:"Slow furnace cooling — softens, increases ductility, relieves stress",note:"Produces the lowest hardness of the common heat treatments."},
{front:"Normalizing",back:"Air cooling from austenitizing temperature — finer grains, moderate hardness",note:"Harder/stronger than annealing, softer than quenching."},
{front:"Quenching",back:"Rapid cooling (water/oil) — maximum hardness, minimum ductility",note:"In steel, traps carbon and forms hard, brittle martensite."},
{front:"Tempering",back:"Reheating a quenched part to a moderate temperature, then cooling",note:"Trades a little hardness for a large gain in toughness — not a full anneal."}
];

const questionsPhaseDiagrams:Question[]=[
{id:"MAT02-Q01",skill:"Eutectic point concept",difficulty:"Easy",prompt:"On a binary eutectic phase diagram, the eutectic point represents:",choices:["The composition and temperature where a single solid phase first begins to melt","The single composition and lowest temperature at which liquid solidifies directly into two solid phases simultaneously","The composition of the pure solvent metal only","The temperature above which every composition in the system is fully liquid"],answer:1,explanation:"The eutectic point is the specific composition/temperature where L→α+β isothermally.",solution:"Step 1 — The eutectic reaction is L→α+β, occurring at one specific composition.\nStep 2 — This composition also has the lowest melting/solidification temperature in the system.\nStep 3 — Solidification there happens at a single, constant temperature, unlike other compositions.\nFinal answer: The single composition and lowest temperature at which liquid solidifies directly into two solid phases simultaneously.",trap:"Choosing 'the temperature above which every composition is fully liquid' describes the overall liquidus envelope in general, not the localized eutectic point, which is one specific composition-temperature pair.",repair:"The eutectic point is a SPECIFIC (composition, temperature) pair, not a general statement about the liquidus line."},
{id:"MAT02-Q02",skill:"Quenching effect",difficulty:"Easy",prompt:"Rapidly quenching a steel from its austenitizing temperature, compared to slow furnace cooling, primarily produces:",choices:["Lower hardness and higher ductility","Higher hardness and lower ductility","No change in mechanical properties","Only a change in density"],answer:1,explanation:"Quenching increases hardness and reduces ductility.",solution:"Step 1 — Rapid cooling traps carbon in a supersaturated, distorted lattice, forming martensite in steel.\nStep 2 — Martensite is much harder and stronger than the microstructures formed by slow cooling, but also much more brittle.\nFinal answer: Higher hardness and lower ductility.",trap:"Choosing 'lower hardness and higher ductility' reverses the actual effect — that describes annealing (slow cooling), not quenching.",repair:"Faster cooling (quenching) raises hardness/strength and lowers ductility; slower cooling (annealing) does the opposite."},
{id:"MAT02-Q03",skill:"Lever rule — liquid fraction",difficulty:"Medium",prompt:"At a given temperature within a two-phase (α+L) region, the overall alloy composition is 32 wt% B. The solidus (α) composition is 20 wt% B and the liquidus (L) composition is 60 wt% B. Using the lever rule, find the weight fraction of liquid phase present.",choices:["0.20","0.30","0.50","0.70"],answer:1,explanation:"The liquid fraction is 0.30.",solution:"Step 1 — Lever rule for the liquid fraction: fraction(L)=(C0−Cα)/(CL−Cα), using the arm on the OPPOSITE side of the liquid.\nStep 2 — Substitute: (32−20)/(60−20)=12/40.\nFinal answer: 0.30 (30% liquid).",trap:"0.70 results from computing the α-phase's arm instead — (CL−C0)/(CL−Cα)=(60−32)/40=0.70 — which is the fraction of the SOLID (α) phase, not the liquid.",repair:"The lever-rule fraction for a phase uses the tie-line arm on the OPPOSITE side of that phase — double-check which phase you're solving for before dividing."},
{id:"MAT02-Q04",skill:"Lever rule — solid fraction",difficulty:"Medium",prompt:"An alloy has an overall composition of 55 wt% Sn. At the temperature of interest, two coexisting phases have compositions of 25 wt% Sn (phase 1) and 75 wt% Sn (phase 2). Find the weight fraction of phase 2.",choices:["0.40","0.50","0.60","0.75"],answer:2,explanation:"The weight fraction of phase 2 is 0.60.",solution:"Step 1 — fraction(phase 2)=(C0−C1)/(C2−C1).\nStep 2 — Substitute: (55−25)/(75−25)=30/50.\nFinal answer: 0.60.",trap:"0.40 is the fraction of phase 1 — (C2−C0)/(C2−C1)=(75−55)/50=0.40 — mistakenly reported instead of the fraction of phase 2, the one actually requested.",repair:"After computing a lever-rule fraction, check that the two phase fractions sum to 1.0 and confirm you're reporting the one the question actually asked for."},
{id:"MAT02-Q05",skill:"Tempering",difficulty:"Medium",prompt:"A steel part is quenched to martensite (very hard but brittle), then tempered by reheating to a moderate temperature below the austenitizing range and holding, then cooling. What is the primary purpose of this tempering step?",choices:["Increase hardness further beyond the as-quenched state","Reduce brittleness and relieve internal stresses while retaining most of the strength gained by quenching","Fully anneal the part back to its original soft, coarse-grained condition","Melt and recast the martensite into a new shape"],answer:1,explanation:"Tempering trades a small amount of hardness for a large gain in toughness.",solution:"Step 1 — As-quenched martensite is very hard but dangerously brittle for most applications.\nStep 2 — Tempering reheats the part to a MODERATE temperature (well below the austenitizing range), allowing some stress relief and microstructural adjustment without fully reversing the hardening.\nStep 3 — The result retains most of the quenched strength while substantially improving toughness.\nFinal answer: Reduce brittleness and relieve internal stresses while retaining most of the strength gained by quenching.",trap:"Choosing 'fully anneal the part back to its original soft condition' overstates tempering's effect — a full anneal uses much higher temperatures and slow furnace cooling, producing a far softer result than tempering.",repair:"Tempering is a controlled, moderate-temperature step that only partially reduces hardness — it is not equivalent to a full anneal."},
{id:"MAT02-Q06",skill:"Normalizing vs. annealing",difficulty:"Medium",prompt:"Compared to full annealing (slow furnace cooling), normalizing a steel (air cooling from the austenitizing temperature) generally produces:",choices:["A softer, more ductile part with coarser grains","A harder, stronger part with a finer grain structure than annealing produces","Identical properties, since both start from the same austenitizing temperature","A part with no measurable change in grain size"],answer:1,explanation:"Normalizing's faster cooling refines grains and increases hardness/strength relative to annealing.",solution:"Step 1 — Both processes start by heating the steel into the austenitizing range.\nStep 2 — Annealing then cools very slowly (in the furnace); normalizing cools faster (in air).\nStep 3 — The faster cooling rate of normalizing produces a finer grain structure and correspondingly higher strength and hardness than the slower-cooled, coarser-grained annealed part.\nFinal answer: A harder, stronger part with a finer grain structure than annealing produces.",trap:"Choosing 'identical properties, since both start from the same austenitizing temperature' ignores that the COOLING RATE — not just the starting temperature — governs the resulting grain size and hardness.",repair:"Cooling rate, not just the starting (austenitizing) temperature, determines the resulting grain size and hardness — faster cooling refines grains and raises hardness."},
{id:"MAT02-Q07",skill:"Lever rule — mass calculation",difficulty:"Hard",prompt:"A 20 kg alloy ingot has an overall composition of 45 wt% Zn. At the processing temperature, it consists of two phases with compositions of 30 wt% Zn and 70 wt% Zn. Find the mass of the phase with 70 wt% Zn present in the ingot.",choices:["5.0 kg","7.5 kg","10.0 kg","12.5 kg"],answer:1,explanation:"The 70 wt% Zn phase makes up 7.5 kg of the ingot.",solution:"Step 1 — Fraction of the 70%-Zn phase=(C0−C_low)/(C_high−C_low)=(45−30)/(70−30)=15/40=0.375.\nStep 2 — Mass=0.375×20 kg.\nFinal answer: 7.5 kg.",trap:"12.5 kg comes from computing the fraction of the OTHER (30 wt% Zn) phase instead — (70−45)/40=0.625, ×20 kg=12.5 kg — and reporting that phase's mass rather than the 70 wt% Zn phase actually requested.",repair:"After applying the lever rule, re-read the question to confirm which phase's mass was actually requested — swapping the tie-line arm gives the complementary phase's mass instead."},
{id:"MAT02-Q08",skill:"Eutectic solidification behavior",difficulty:"Hard",prompt:"A eutectic-composition alloy, upon slow cooling from the liquid, solidifies at:",choices:["A single, constant temperature, transforming directly from liquid into two solid phases","A range of temperatures, like most other compositions in the system","A temperature above the liquidus of either pure component","Only after every other composition in the system has finished solidifying"],answer:0,explanation:"The eutectic composition solidifies isothermally, unlike off-eutectic compositions.",solution:"Step 1 — Off-eutectic compositions solidify over a range of temperatures, between their liquidus and solidus.\nStep 2 — The eutectic composition is the special case where liquidus and solidus meet at a single point.\nStep 3 — Solidification there therefore occurs at one constant temperature, analogous to a pure metal's solidification.\nFinal answer: A single, constant temperature, transforming directly from liquid into two solid phases.",trap:"Choosing 'a range of temperatures, like most other compositions' describes off-eutectic (hypoeutectic/hypereutectic) alloys — the eutectic composition is specifically the exception that solidifies isothermally.",repair:"Only the EXACT eutectic composition solidifies at one constant temperature; every other composition in the system solidifies over a temperature range."},
{id:"MAT02-Q09",skill:"Single-phase region concepts",difficulty:"Medium",prompt:"A binary alloy's overall composition and temperature place it inside a single-phase (all-liquid) region of the phase diagram. How many phases are present, and how is that phase's fraction determined?",choices:["Two phases; the lever rule gives a 50/50 split","One phase; its fraction is trivially 1.0, since there's no tie line to apply the lever rule to","Zero phases; the material is mid-transformation","One phase; its fraction must still be computed from the lever rule using nearby tie lines"],answer:1,explanation:"Inside a single-phase region, that one phase's fraction is trivially 1.0.",solution:"Step 1 — A single-phase region contains only one distinct phase, by definition.\nStep 2 — The lever rule requires a tie line connecting two DIFFERENT coexisting phase compositions, which doesn't exist inside a single-phase field.\nStep 3 — With only one phase present, its fraction of the total is simply 1.0 — no calculation is needed.\nFinal answer: One phase; its fraction is trivially 1.0, since there's no tie line to apply the lever rule to.",trap:"Choosing 'its fraction must still be computed from the lever rule using nearby tie lines' incorrectly extends a two-phase-region tool into a single-phase region where it doesn't apply.",repair:"The lever rule applies ONLY inside two-phase regions with an actual tie line — a single-phase field's fraction is always 1.0 by definition."},
{id:"MAT02-Q10",skill:"Heat treatment hardness ranking",difficulty:"Hard",prompt:"Rank the following heat treatments, from LOWEST to HIGHEST resulting hardness for the same steel: annealing, normalizing, quenching.",choices:["Quenching < Normalizing < Annealing","Annealing < Normalizing < Quenching","Normalizing < Annealing < Quenching","Annealing < Quenching < Normalizing"],answer:1,explanation:"Hardness increases with cooling rate: annealing < normalizing < quenching.",solution:"Step 1 — Annealing uses the slowest cooling rate → softest, most ductile, lowest hardness.\nStep 2 — Normalizing uses a faster (air) cooling rate → moderate hardness, finer grains than annealing.\nStep 3 — Quenching uses the fastest cooling rate → highest hardness (martensite in steel), though most brittle.\nFinal answer: Annealing < Normalizing < Quenching.",trap:"Choosing 'Quenching < Normalizing < Annealing' reverses the entire ranking, treating the slowest cooling (annealing) as if it produced the greatest hardness.",repair:"Rank strictly by cooling rate: faster cooling produces higher hardness, up through quenching's martensite formation."}
];

export const materialsPhaseDiagramsModule:StudyModule={id:"MAT-02",subjectId:"materials",sectionId:"phase-diagrams",title:"Phase Diagrams and Heat Treatment",lessons:lessonsPhaseDiagrams,flashcards:flashcardsPhaseDiagrams,questions:questionsPhaseDiagrams};

// ---------- MAT-03: Manufacturing Processes ----------

const lessonsManufacturing=[
{title:"Casting processes",body:"Sand casting uses low-cost, expendable sand molds — suited for low-to-medium volumes, larger parts, and a wide range of alloys, but with looser dimensional tolerances and a rougher surface finish. Die casting forces molten metal into reusable, precision metal dies under pressure — it gives tight tolerances and excellent surface finish but requires expensive tooling, so it is economical only at high production volumes, and is generally limited to lower-melting-point nonferrous alloys (aluminum, zinc, magnesium). Investment (lost-wax) casting uses an expendable wax pattern coated in a ceramic shell, melted out before pouring — it produces excellent surface finish and tight tolerances for complex, lower-volume parts such as turbine blades, across a much wider range of alloys than die casting."},
{title:"Bulk forming processes",body:"Rolling, forging, and extrusion all reshape metal through plastic deformation rather than removing material. Hot working (above the recrystallization temperature) keeps forming forces low and avoids strain hardening, since new strain-free grains continuously form during deformation. Cold working (below the recrystallization temperature) increases strength and hardness through strain hardening but reduces ductility, and requires higher forming forces. Forged parts often have superior strength and fatigue resistance compared to an identical part machined from bar stock, because forging aligns the internal grain flow along the part's load path instead of cutting across it."},
{title:"Machining",body:"Machining (turning, milling, drilling, grinding) is a subtractive process that removes material with a cutting tool to achieve tight tolerances and fine surface finishes that casting or forming alone often cannot. Because it removes material (and time) rather than adding or reshaping it, machining an entire complex part from solid bar stock is usually far less economical than combining a near-net-shape primary process (casting or forging) with machining reserved only for the features that truly require tight tolerances."},
{title:"Joining processes",body:"Fusion welding melts and fuses base metal (often with filler metal) at the joint, creating a fusion zone. Adjacent to the fusion zone, the heat-affected zone (HAZ) did not melt but still had its microstructure and properties altered by the nearby welding heat — it is a common source of reduced strength or toughness in a welded joint. Mechanical fasteners and adhesive bonding are joining alternatives that avoid melting the base metal entirely, useful when a HAZ or thermal distortion is undesirable."}
];

const flashcardsManufacturing=[
{front:"Sand casting",back:"Low tooling cost, looser tolerances, rougher finish",note:"Economical at low-to-medium volume; wide alloy range."},
{front:"Die casting",back:"High tooling cost, tight tolerances, excellent finish",note:"Economical only at high volume; mainly nonferrous alloys."},
{front:"Investment (lost-wax) casting",back:"Expendable wax pattern + ceramic shell → excellent finish/tolerance",note:"Good for complex, lower-volume parts like turbine blades."},
{front:"Hot working",back:"Deformation above recrystallization temperature",note:"Low forming forces, no significant strain hardening — grains continuously recrystallize."},
{front:"Cold working",back:"Deformation below recrystallization temperature",note:"Increases strength/hardness via strain hardening, but reduces ductility."},
{front:"Extrusion ratio",back:"R=A0/Af (billet area ÷ final product area)",note:"Confirm which area is in the numerator."},
{front:"Heat-affected zone (HAZ)",back:"Region next to a weld that didn't melt but was thermally altered",note:"Distinct from the fusion zone, which did melt and mix with filler."}
];

const questionsManufacturing:Question[]=[
{id:"MAT03-Q01",skill:"Casting process selection",difficulty:"Easy",prompt:"Which casting process is best suited for producing a small number of complex, thin-walled parts with excellent surface finish and tight tolerances, such as turbine blades, using expendable wax patterns?",choices:["Sand casting","Die casting","Investment (lost-wax) casting","Continuous casting"],answer:2,explanation:"Investment casting is the classic choice for complex, high-finish, lower-volume parts like turbine blades.",solution:"Step 1 — Sand casting gives loose tolerances/rough finish — not adequate here.\nStep 2 — Die casting gives excellent finish/tolerance but needs expensive reusable metal dies, is economical only at HIGH volume, and mainly suits nonferrous alloys — a poor fit for a small quantity of complex, often high-temperature-alloy parts.\nStep 3 — Investment casting uses an expendable wax pattern in a ceramic shell, giving excellent finish/tolerance for complex geometries across a wide alloy range, at low-to-moderate volumes.\nFinal answer: Investment (lost-wax) casting.",trap:"Choosing 'die casting' focuses only on its good finish/tolerance and ignores that it requires expensive reusable dies, is economical only at high volumes, and is largely limited to lower-melting nonferrous alloys — a mismatch for a small run of complex parts.",repair:"Match the process to BOTH the part geometry/material AND the production volume/cost tradeoff, not just the achievable finish or tolerance."},
{id:"MAT03-Q02",skill:"Hot working vs. cold working",difficulty:"Easy",prompt:"Compared to cold working, hot working a metal (deforming it above its recrystallization temperature) generally results in:",choices:["Higher strength and lower ductility due to strain hardening","Lower forming forces and no significant strain hardening, since new strain-free grains continuously form","Identical mechanical properties, since temperature does not affect deformation","A rougher surface finish but tighter dimensional tolerances than cold working"],answer:1,explanation:"Hot working recrystallizes continuously, avoiding strain hardening and keeping forming forces low.",solution:"Step 1 — Cold working (below recrystallization temperature) accumulates dislocations, raising strength/hardness while lowering ductility — this is strain hardening.\nStep 2 — Hot working (above recrystallization temperature) continuously forms new, strain-free grains as deformation proceeds, so strain hardening does not accumulate.\nStep 3 — This keeps required forming forces relatively low during hot working.\nFinal answer: Lower forming forces and no significant strain hardening, since new strain-free grains continuously form.",trap:"Choosing 'higher strength and lower ductility due to strain hardening' actually describes COLD working — hot working avoids that buildup because it recrystallizes continuously.",repair:"Strain hardening accumulates during cold working; hot working recrystallizes continuously and avoids it — keep the two mechanisms straight."},
{id:"MAT03-Q03",skill:"Extrusion ratio",difficulty:"Medium",prompt:"A cylindrical billet with a cross-sectional area of 8000 mm² is extruded through a die to produce a rod with a cross-sectional area of 500 mm². Find the extrusion ratio.",choices:["0.0625","6.25","16.0","62.5"],answer:2,explanation:"The extrusion ratio is 16.",solution:"Step 1 — Extrusion ratio R=A0/Af (billet area over final product area).\nStep 2 — R=8000/500.\nFinal answer: 16.0.",trap:"0.0625 results from inverting the ratio (Af/A0=500/8000) instead of using the standard A0/Af definition.",repair:"The extrusion ratio is conventionally the STARTING (billet) area divided by the FINAL (product) area — confirm which area belongs in the numerator."},
{id:"MAT03-Q04",skill:"Near-net-shape vs. machining",difficulty:"Medium",prompt:"A part must be produced in high volume with tight tolerances on only a few critical features, but the overall shape is complex. Which manufacturing strategy is most economical?",choices:["Machine the entire part from solid bar stock","Produce a near-net-shape part by casting or forging, then machine only the critical features","Use only sand casting with no further processing","Use only manual filing and grinding to finish a raw casting"],answer:1,explanation:"Combining a near-net-shape process with targeted machining minimizes both material waste and machining cost.",solution:"Step 1 — Machining the entire complex shape from solid bar stock wastes large amounts of material and machine time on features that don't need tight tolerances.\nStep 2 — Sand casting alone (or hand-finishing) can't reliably deliver tight tolerances on the critical features.\nStep 3 — Producing a near-net-shape blank by casting or forging, then machining only the critical features, minimizes both wasted material and machining time.\nFinal answer: Produce a near-net-shape part by casting or forging, then machine only the critical features.",trap:"Choosing 'machine the entire part from solid bar stock' overlooks that most of the complex geometry could be formed far more efficiently by a near-net-shape process, reserving machining only for the features that truly need it.",repair:"Reserve machining for the features that actually require tight tolerances or fine finish; let a near-net-shape process (casting/forging) generate the bulk geometry."},
{id:"MAT03-Q05",skill:"Rolling reduction",difficulty:"Medium",prompt:"A steel slab enters a rolling mill with a thickness of 40 mm and exits at a thickness of 28 mm. Find the percent reduction in thickness.",choices:["12.0%","28.0%","30.0%","70.0%"],answer:2,explanation:"The percent reduction in thickness is 30.0%.",solution:"Step 1 — %reduction=(t0−tf)/t0×100.\nStep 2 — Substitute: (40−28)/40×100=12/40×100.\nFinal answer: 30.0%.",trap:"70.0% comes from computing tf/t0×100=28/40×100=70%, which is the fraction of thickness REMAINING, not the percent reduction.",repair:"Percent reduction is the CHANGE divided by the original value — it is the complement of (and not the same as) the remaining-thickness fraction."},
{id:"MAT03-Q06",skill:"Heat-affected zone",difficulty:"Medium",prompt:"In a fusion-welded steel joint, the heat-affected zone (HAZ) refers to the region:",choices:["Where the filler metal and base metal fully melt and mix together","Adjacent to the weld, where the base metal did not melt but its microstructure and properties were altered by the welding heat","Farthest from the weld, entirely unaffected by the process","Where the electrode tip physically contacts the workpiece"],answer:1,explanation:"The HAZ is the solid region adjacent to the weld whose properties were changed by the heat, without melting.",solution:"Step 1 — The fusion zone is where filler metal and base metal actually melt and mix — that's a separate region from the HAZ.\nStep 2 — Adjacent to the fusion zone, base metal experiences high temperatures without melting, which can still alter grain size and microstructure.\nStep 3 — This solid-but-thermally-altered region is defined as the heat-affected zone (HAZ), a common source of reduced strength or toughness near a weld.\nFinal answer: Adjacent to the weld, where the base metal did not melt but its microstructure and properties were altered by the welding heat.",trap:"Choosing 'where the filler metal and base metal fully melt and mix' describes the FUSION zone, not the HAZ — the HAZ specifically stayed solid.",repair:"Keep the fusion zone (melted, mixed with filler) and the heat-affected zone (solid, thermally altered) as two distinct, adjacent regions of a weld."},
{id:"MAT03-Q07",skill:"Process economics — break-even quantity",difficulty:"Hard",prompt:"A manufacturer is choosing between sand casting (tooling cost $2,000, per-part cost $8) and die casting (tooling cost $18,000, per-part cost $3) for an aluminum bracket. At what production quantity do the two processes have the same total cost?",choices:["1,600 parts","2,000 parts","3,200 parts","4,500 parts"],answer:2,explanation:"The break-even quantity is 3,200 parts.",solution:"Step 1 — Total cost, sand casting: 2000+8x. Total cost, die casting: 18000+3x.\nStep 2 — Set them equal: 2000+8x=18000+3x.\nStep 3 — Collect variable terms: 8x−3x=18000−2000, so 5x=16000.\nStep 4 — Solve: x=16000/5.\nFinal answer: 3,200 parts.",trap:"1,600 parts results from dividing the constant difference (16,000) by 10 instead of the correct coefficient difference of 5 (8−3), understating the break-even quantity by half.",repair:"Isolate the variable terms first (8x−3x=5x) and divide by that exact coefficient — don't guess at the divisor."},
{id:"MAT03-Q08",skill:"Forging vs. machining — grain flow",difficulty:"Hard",prompt:"A steel connecting rod is manufactured by forging, which aligns the material's internal grain flow along the part's contour, compared to an identical part machined entirely from bar stock (which can cut across the grain in some regions). Which statement is correct?",choices:["The machined part has superior fatigue strength because machining removes surface defects","The forged part generally has superior strength and fatigue resistance, because the continuous grain flow follows the load path and avoids exposing grain ends at the surface","Grain flow has no effect on mechanical properties — only chemical composition matters","The forged part is always more brittle than the machined part due to work hardening"],answer:1,explanation:"Continuous, load-path-aligned grain flow from forging typically improves strength and fatigue resistance over a machined-from-stock part of identical composition.",solution:"Step 1 — Forging plastically deforms the material to follow the part's contour, keeping the grain flow continuous along the load path.\nStep 2 — Machining from bar stock can cut across this grain flow, exposing grain boundaries/ends at the surface, which can act as crack initiation sites.\nStep 3 — For otherwise identical composition, this makes forged parts generally superior in strength and especially fatigue resistance for load-path-critical components.\nFinal answer: The forged part generally has superior strength and fatigue resistance, because the continuous grain flow follows the load path and avoids exposing grain ends at the surface.",trap:"Choosing 'only chemical composition matters' ignores that microstructural/geometric factors like grain flow orientation meaningfully affect strength and fatigue life even for identical chemistry.",repair:"Recognize that grain flow orientation (continuous in forgings vs. potentially interrupted in machined-from-stock parts) is a real, exam-relevant factor in fatigue performance — not just chemical composition."},
{id:"MAT03-Q09",skill:"Casting process tradeoffs",difficulty:"Medium",prompt:"Which of the following is a well-known limitation of sand casting compared to die casting?",choices:["Sand casting cannot produce internal cavities or hollow sections","Sand casting generally has looser dimensional tolerances and a rougher surface finish","Sand casting requires expensive permanent metal dies","Sand casting is limited to only nonferrous metals"],answer:1,explanation:"Sand casting trades tooling cost for looser tolerances and rougher finish.",solution:"Step 1 — Sand casting uses low-cost, expendable sand molds, not reusable metal dies — that rules out the 'expensive permanent dies' option, which actually describes die casting.\nStep 2 — Sand molds can accommodate cores for internal cavities, so that option is also incorrect.\nStep 3 — Sand casting can cast a very wide range of alloys, including ferrous metals, unlike die casting's largely nonferrous scope.\nStep 4 — The genuine tradeoff is that sand casting's looser mold tolerances and coarser mold surface generally produce looser dimensional tolerances and a rougher finish than die casting.\nFinal answer: Sand casting generally has looser dimensional tolerances and a rougher surface finish.",trap:"Choosing 'requires expensive permanent metal dies' describes die casting's tooling requirement — essentially the opposite of sand casting, which uses low-cost, expendable sand molds.",repair:"Keep the tooling-cost/tolerance tradeoff straight: sand casting = low tooling cost, looser tolerances; die casting = high tooling cost, tighter tolerances."},
{id:"MAT03-Q10",skill:"Process classification",difficulty:"Easy",prompt:"Which manufacturing process is a material-removal (subtractive) process rather than a forming or casting process?",choices:["Forging","Extrusion","Milling (machining)","Sand casting"],answer:2,explanation:"Milling removes material with a cutting tool; the others form or cast material without removing it.",solution:"Step 1 — Forging and extrusion are bulk-deformation (forming) processes — they reshape material without removing any of it.\nStep 2 — Sand casting is a solidification process — molten metal is poured and solidifies into a near-net shape.\nStep 3 — Milling uses a rotating cutting tool to physically remove material from a workpiece — the defining feature of a subtractive (machining) process.\nFinal answer: Milling (machining).",trap:"Choosing 'extrusion' misclassifies a bulk-deformation (forming) process — extrusion pushes material through a die without removing any of it — as if it were subtractive like milling.",repair:"Sort processes into families first — casting (solidification), forming (bulk deformation, no removal), machining (material removal) — before answering a classification question."}
];

export const materialsManufacturingModule:StudyModule={id:"MAT-03",subjectId:"materials",sectionId:"manufacturing",title:"Manufacturing Processes",lessons:lessonsManufacturing,flashcards:flashcardsManufacturing,questions:questionsManufacturing};

// ---------- MAT-04: Failure and Material Selection ----------

const lessonsFailure=[
{title:"Ductile vs. brittle fracture",body:"Ductile fracture shows significant plastic deformation before failure — visible necking and a characteristic cup-and-cone fracture surface in a round tensile specimen. Brittle fracture occurs with little or no plastic deformation, a flat/granular fracture surface, and can happen suddenly with little warning. Many body-centered-cubic metals (like steel) exhibit a ductile-to-brittle transition temperature (DBTT): the same part that behaves ductilely at room temperature can fail in a brittle manner in cold weather, a classic cause of historical structural failures."},
{title:"Fatigue and the S-N curve",body:"Under cyclic loading, a part can fail at a stress far below its static strength — this is fatigue. An S-N curve plots stress amplitude, σa=(σmax−σmin)/2, against the number of cycles to failure (log scale). Steel and some titanium alloys show a true endurance limit — a stress amplitude below which fatigue life is essentially infinite — while many nonferrous metals, including most aluminum alloys, do not, so their fatigue strength must be specified at a stated number of cycles. Fatigue cracks nearly always initiate at surface stress concentrations, so smoother finishes, generous fillets, and compressive residual stress (e.g., shot peening) improve fatigue life, while a higher mean stress at the same amplitude reduces it."},
{title:"Creep",body:"Creep is slow, time-dependent plastic deformation under a sustained (often constant) stress, significant mainly at elevated temperature (roughly above 0.4 times the absolute melting temperature). A creep curve has three stages: primary (decreasing strain rate), secondary/steady-state (an approximately constant, minimum strain rate — typically used for design-life estimates), and tertiary (accelerating strain rate leading to rupture). Creep is a major design consideration for components operating at high temperature, such as turbine blades and boiler piping."},
{title:"Material selection tradeoffs",body:"Choosing a material means balancing multiple criteria: strength, specific strength (strength/density, key for weight-critical parts), specific stiffness (E/density, key when deflection rather than strength governs), corrosion resistance, manufacturability, and cost. Specific strength varies significantly between materials (aluminum's is often much higher than steel's), but specific stiffness is nearly the same for most structural metals — steel and aluminum both have E/ρ near 25 GPa per Mg/m³ — so a stiffness-critical design often can't be improved much by switching between them alone."}
];

const flashcardsFailure=[
{front:"Ductile fracture",back:"Cup-and-cone surface, significant necking before failure",note:"Signals extensive plastic deformation."},
{front:"Brittle fracture",back:"Flat/granular surface, little or no plastic deformation",note:"Can occur suddenly, with little warning."},
{front:"Stress amplitude",back:"σa=(σmax−σmin)/2",note:"Don't confuse with mean stress σm=(σmax+σmin)/2."},
{front:"Endurance limit",back:"Stress amplitude below which fatigue life is essentially infinite",note:"True for steel/some titanium alloys; NOT true for most aluminum alloys."},
{front:"Creep — secondary stage",back:"Approximately constant, minimum strain rate",note:"Used for long-term design-life estimates; tertiary stage accelerates to rupture."},
{front:"Specific strength",back:"Strength ÷ density",note:"Key metric for weight-critical, strength-governed design."},
{front:"Specific stiffness",back:"E ÷ density",note:"Nearly equal for steel and aluminum (~25 GPa per Mg/m³) — unlike specific strength."}
];

const questionsFailure:Question[]=[
{id:"MAT04-Q01",skill:"Fracture mode identification",difficulty:"Easy",prompt:"A fractured tensile specimen shows a cup-and-cone surface with significant necking prior to failure. This fracture is classified as:",choices:["Brittle fracture","Fatigue fracture","Ductile fracture","Creep rupture"],answer:2,explanation:"Cup-and-cone with necking is the classic ductile fracture signature.",solution:"Step 1 — Significant necking indicates extensive plastic deformation occurred before failure.\nStep 2 — A cup-and-cone surface is the classic geometric signature of this plastic-deformation-dominated failure mode.\nFinal answer: Ductile fracture.",trap:"Choosing 'fatigue fracture' overlooks that fatigue fractures typically show beach marks/striations from repeated cyclic loading and little overall necking — not the single-overload cup-and-cone shape described.",repair:"Identify fracture mode from its characteristic surface appearance: cup-and-cone with necking = ductile overload; beach marks/striations = fatigue; flat/granular = brittle."},
{id:"MAT04-Q02",skill:"Endurance limit",difficulty:"Easy",prompt:"Which class of metal is well known for NOT exhibiting a true endurance limit — meaning it can eventually fail in fatigue even at low stress amplitudes, given enough cycles?",choices:["Steel","Aluminum","Titanium (some alloys)","Cast iron"],answer:1,explanation:"Aluminum alloys generally lack a true endurance limit.",solution:"Step 1 — Steel and some titanium alloys show an S-N curve that flattens out at a finite stress amplitude — the endurance limit.\nStep 2 — Aluminum alloys' S-N curves keep declining without flattening, so there's no stress amplitude that guarantees infinite life.\nStep 3 — For this reason, aluminum fatigue strength is specified at a stated number of cycles instead of as a true endurance limit.\nFinal answer: Aluminum.",trap:"Choosing 'steel' picks the classic material that DOES exhibit a true endurance limit — the opposite of what the question asks for.",repair:"Remember the exception, not the rule: steel and some titanium alloys have an endurance limit; aluminum and many other nonferrous metals do not."},
{id:"MAT04-Q03",skill:"Specific strength",difficulty:"Medium",prompt:"Material A has a yield strength of 250 MPa and a density of 7850 kg/m³. Material B has a yield strength of 310 MPa and a density of 2700 kg/m³. Find the specific strength (yield strength ÷ density) of Material B, in MPa per g/cm³.",choices:["31.8 MPa per g/cm³","41.9 MPa per g/cm³","114.8 MPa per g/cm³","837.0 MPa per g/cm³"],answer:2,explanation:"Material B's specific strength is about 114.8 MPa per g/cm³.",solution:"Step 1 — Convert density to g/cm³: 2700 kg/m³=2.70 g/cm³.\nStep 2 — Specific strength=σy/ρ=310 MPa/2.70 g/cm³.\nFinal answer: 114.8 MPa per g/cm³.",trap:"31.8 MPa per g/cm³ is Material A's specific strength (250/7.85), mistakenly computed instead of Material B's, the one actually requested.",repair:"Confirm which material's properties the question asks for before substituting numbers — don't default to the first data set given."},
{id:"MAT04-Q04",skill:"Ductile-to-brittle transition",difficulty:"Medium",prompt:"A steel structure that behaves in a ductile manner at room temperature can fail in a brittle manner in cold weather. This behavior is best explained by:",choices:["The material's density changing significantly with temperature","The ductile-to-brittle transition temperature (DBTT), below which BCC metals like steel lose much of their impact toughness","An increase in elastic modulus at low temperature that has no effect on fracture mode","Accelerated corrosion at low temperature"],answer:1,explanation:"Cold-weather brittle failure in steel is the classic DBTT phenomenon.",solution:"Step 1 — Body-centered-cubic metals such as steel show a strong temperature dependence in their fracture behavior.\nStep 2 — Above the DBTT, the material absorbs significant energy and deforms plastically before fracturing (ductile).\nStep 3 — Below the DBTT, the same material fractures with little plastic deformation and much lower absorbed energy (brittle) — the classic cause of cold-weather structural failures.\nFinal answer: The ductile-to-brittle transition temperature (DBTT), below which BCC metals like steel lose much of their impact toughness.",trap:"Choosing the elastic-modulus option treats a minor stiffness change as the explanation, missing the dominant, exam-relevant DBTT phenomenon specific to BCC metals like steel.",repair:"Tie 'brittle failure in cold weather' directly to the ductile-to-brittle transition temperature — a hallmark FE topic distinct from simple stiffness or corrosion effects."},
{id:"MAT04-Q05",skill:"Fatigue life factors",difficulty:"Medium",prompt:"Which design change is LEAST likely to improve a part's fatigue life?",choices:["Polishing the surface to remove machining marks","Adding a generous fillet radius at a shaft shoulder instead of a sharp corner","Increasing the mean stress while holding the same stress amplitude","Shot peening the surface to introduce beneficial residual compressive stress"],answer:2,explanation:"Raising the mean stress (at constant amplitude) generally reduces fatigue life, unlike the other listed changes.",solution:"Step 1 — Fatigue cracks nearly always initiate at surface stress concentrations, so a smoother surface, a generous fillet, and compressive residual stress (shot peening) all help fatigue life.\nStep 2 — Increasing the mean stress while keeping the same stress amplitude generally REDUCES fatigue life, per standard mean-stress (Goodman-type) relationships.\nFinal answer: Increasing the mean stress while holding the same stress amplitude.",trap:"Choosing 'polishing the surface' as the least effective change is backwards — smoother surface finish is one of the most effective ways to improve fatigue life, since cracks nearly always start at surface imperfections.",repair:"Rank design changes by their known effect on fatigue life: smoother surface, generous fillets, and compressive residual stress all help; raising mean stress at the same amplitude hurts."},
{id:"MAT04-Q06",skill:"Creep stages",difficulty:"Hard",prompt:"During the secondary (steady-state) stage of a creep curve, the strain rate is:",choices:["Continuously increasing until rupture","Approximately constant, representing the minimum creep rate","Zero, since no additional deformation occurs","Only observed in brittle ceramic materials"],answer:1,explanation:"The secondary stage has an approximately constant, minimum creep rate.",solution:"Step 1 — The primary stage starts with a relatively high strain rate that decreases as the material work-hardens.\nStep 2 — The secondary (steady-state) stage follows, with the strain rate leveling off to an approximately constant, minimum value — the stage typically used for long-term design-life estimates.\nStep 3 — The tertiary stage then follows, with strain rate accelerating rapidly until rupture.\nFinal answer: Approximately constant, representing the minimum creep rate.",trap:"Choosing 'continuously increasing until rupture' describes the TERTIARY stage, not the roughly constant, minimum-rate secondary stage.",repair:"Keep the three creep stages distinct: primary (decreasing rate), secondary (constant, minimum rate), tertiary (accelerating rate to rupture)."},
{id:"MAT04-Q07",skill:"Specific stiffness comparison",difficulty:"Hard",prompt:"A designer must choose between two candidate materials for a weight-critical tension member where deflection (stiffness), not strength, governs the design. Material X: E=70 GPa, ρ=2700 kg/m³. Material Y: E=200 GPa, ρ=7850 kg/m³. Using specific stiffness (E/ρ) as the selection index, how do the two materials compare?",choices:["Material X is about 5× stiffer per unit weight than Y","Material Y is about 3× stiffer per unit weight than X","The two materials have nearly equal specific stiffness (E/ρ), differing by less than 5%","Specific stiffness cannot be computed without knowing the cross-sectional area"],answer:2,explanation:"Steel and aluminum have nearly identical specific stiffness, despite their very different raw modulus and density values.",solution:"Step 1 — Convert densities to Mg/m³: ρX=2.70, ρY=7.85.\nStep 2 — Specific stiffness of X: E/ρ=70/2.70=25.9 GPa per Mg/m³.\nStep 3 — Specific stiffness of Y: E/ρ=200/7.85=25.5 GPa per Mg/m³.\nStep 4 — The two values differ by only about 1.7%.\nFinal answer: The two materials have nearly equal specific stiffness (differing by less than 5%) — a well-known result: aluminum and steel have similar E/ρ, unlike specific strength, which varies far more between materials.",trap:"Choosing 'Material Y is about 3× stiffer per unit weight' comes from comparing only the raw modulus values (200/70≈2.9) without dividing each by its own density, ignoring that Y is also much denser.",repair:"Specific stiffness requires dividing EACH material's modulus by ITS OWN density before comparing — comparing raw modulus values alone ignores the weight penalty of the denser material."},
{id:"MAT04-Q08",skill:"Impact toughness testing",difficulty:"Medium",prompt:"The Charpy V-notch impact test is primarily used to evaluate a material's:",choices:["Tensile strength under static loading","Resistance to sudden fracture (toughness) under impact loading, especially near the ductile-to-brittle transition","Hardness on the Rockwell C scale","Fatigue endurance limit"],answer:1,explanation:"The Charpy test measures impact toughness and DBTT behavior, not static strength, hardness, or fatigue life.",solution:"Step 1 — A standard tension test, not the Charpy test, measures static tensile strength and ductility.\nStep 2 — A hardness test (Rockwell, Brinell) measures resistance to indentation, again not the Charpy test's purpose.\nStep 3 — The Charpy V-notch test strikes a notched specimen with a swinging pendulum and measures the energy absorbed during a rapid fracture — this quantifies toughness, and is often repeated across temperatures to find the ductile-to-brittle transition.\nFinal answer: Resistance to sudden fracture (toughness) under impact loading, especially near the ductile-to-brittle transition.",trap:"Choosing 'tensile strength under static loading' assigns the Charpy test the role of a standard tension test, which measures an entirely different (static, not impact) property.",repair:"Match each test to what it measures: tension test → strength/ductility (static); Charpy impact → toughness/DBTT (dynamic, notched); hardness test → resistance to indentation."},
{id:"MAT04-Q09",skill:"Stress amplitude and mean stress",difficulty:"Medium",prompt:"A rotating shaft experiences a cyclic bending stress that varies from a maximum of 180 MPa (tension) to a minimum of −60 MPa (compression) each cycle. Find the stress amplitude, σa.",choices:["60 MPa","90 MPa","120 MPa","180 MPa"],answer:2,explanation:"The stress amplitude is 120 MPa.",solution:"Step 1 — σa=(σmax−σmin)/2.\nStep 2 — Substitute: (180−(−60))/2=240/2.\nFinal answer: 120 MPa.",trap:"60 MPa is actually the MEAN stress, σm=(σmax+σmin)/2=(180−60)/2=60 MPa, mistakenly reported instead of the amplitude.",repair:"Keep the two S-N loading parameters distinct: amplitude σa uses the DIFFERENCE (σmax−σmin)/2; mean stress σm uses the SUM (σmax+σmin)/2."},
{id:"MAT04-Q10",skill:"Material selection criteria",difficulty:"Easy",prompt:"A design requires a component that is lightweight, corrosion-resistant, and moderately strong; the problem explicitly states that cost is a secondary concern. Which factor should generally NOT be the primary driver of the material selection decision in this scenario?",choices:["Specific strength (strength-to-weight ratio)","Corrosion resistance in the service environment","Raw material cost per kilogram","Compatibility with the required manufacturing process"],answer:2,explanation:"Cost was explicitly stated as secondary, so it should not be the primary selection driver here.",solution:"Step 1 — The problem explicitly ranks weight, corrosion resistance, and moderate strength as the priorities.\nStep 2 — It also explicitly states cost is secondary in this scenario.\nStep 3 — Manufacturability remains a practical constraint regardless of the stated priorities, so it stays relevant; cost is the one factor the problem tells you to de-prioritize.\nFinal answer: Raw material cost per kilogram.",trap:"Choosing 'compatibility with the required manufacturing process' treats manufacturability as if it were optional, when it remains a valid practical constraint in virtually any selection scenario — cost was the one explicitly de-prioritized factor.",repair:"When a problem explicitly ranks selection criteria, let the STATED priorities (not assumed universal factors) determine which consideration is 'secondary' in that specific scenario."}
];

